using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedLabel { get; set; } = string.Empty;

    [ColumnName("Score")]
    public float[] Score { get; set; } = [];
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelService
{
    private readonly MLContext _mlContext;
    private readonly ILogger<TicketModelService> _logger;
    private ITransformer? _model;
    private DataViewSchema? _schema;

    public string ModelPath { get; }

    public TicketModelService(ILogger<TicketModelService> logger, IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);
        _logger = logger;
        ModelPath = Path.Combine(env.ContentRootPath, "Data", "TicketModel.zip");
    }

    public void TrainAndEvaluate()
    {
        var dataPath = Path.Combine(Path.GetDirectoryName(ModelPath)!, "tickets.csv");

        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training ticket classification model...");
        _model = pipeline.Fit(split.TrainSet);
        _schema = split.TrainSet.Schema;

        // Evaluate on test set
        var predictions = _model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        _logger.LogInformation("Model evaluation metrics:");
        _logger.LogInformation("  MacroAccuracy:    {MacroAccuracy:F4}", metrics.MacroAccuracy);
        _logger.LogInformation("  LogLoss:          {LogLoss:F4}", metrics.LogLoss);
        _logger.LogInformation("  LogLossReduction: {LogLossReduction:F4}", metrics.LogLossReduction);

        // Save model
        _mlContext.Model.Save(_model, _schema, ModelPath);
        _logger.LogInformation("Model saved to {ModelPath}", ModelPath);
    }

    public (ITransformer Model, DataViewSchema Schema) GetModelAndSchema()
    {
        return (_model ?? throw new InvalidOperationException("Model not trained yet."),
                _schema ?? throw new InvalidOperationException("Schema not available yet."));
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

public record ClassifyRequest(string Subject, string Description, float Priority);

public record ClassifyResponse(string PredictedCategory, Dictionary<string, float> ConfidenceScores);

[ApiController]
[Route("api/tickets")]
public class TicketController : ControllerBase
{
    private static readonly string[] Categories = ["Technical", "Billing", "General"];

    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;

    public TicketController(PredictionEnginePool<TicketInput, TicketPrediction> predictionPool)
    {
        _predictionPool = predictionPool;
    }

    [HttpPost("classify")]
    public ActionResult<ClassifyResponse> Classify([FromBody] ClassifyRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < Categories.Length; i++)
        {
            scores[Categories[i]] = prediction.Score[i];
        }

        return Ok(new ClassifyResponse(prediction.PredictedLabel, scores));
    }

    [HttpGet("categories")]
    public ActionResult<string[]> GetCategories()
    {
        return Ok(Categories);
    }
}

